// This file is not generated by Speakeasy. It carries the defaults a linked
// project (.voiceflow/project.json, see internal/link) supplies, at the
// lowest precedence: an explicit flag, then --body or stdin, then the link.

package flagutil

import (
	"fmt"
	"reflect"
	"strings"

	"github.com/spf13/cobra"
	"github.com/spf13/pflag"
)

// LinkDefaultAnnotation marks a flag whose value came from a linked project
// rather than from the command line.
const LinkDefaultAnnotation = "vf.link.default"

// SetLinkDefault gives a flag a linked project's value without marking it as
// set by the user. BuildRequest then treats it as a fallback: it fills a
// required path or query parameter, and any field that the flags, --body and
// stdin all left empty, but it never replaces a value the user supplied.
func SetLinkDefault(cmd *cobra.Command, name, value string) error {
	f := lookupFlag(cmd, name)
	if f == nil {
		return fmt.Errorf("the command has no --%s flag", name)
	}
	if err := f.Value.Set(value); err != nil {
		return err
	}
	if f.Annotations == nil {
		f.Annotations = map[string][]string{}
	}
	f.Annotations[LinkDefaultAnnotation] = []string{value}
	return nil
}

// HasLinkDefault reports whether a flag holds a value from a linked project.
func HasLinkDefault(cmd *cobra.Command, name string) bool {
	_, ok := linkDefault(cmd, name)
	return ok
}

func linkDefault(cmd *cobra.Command, name string) (string, bool) {
	f := lookupFlag(cmd, name)
	if f == nil || len(f.Annotations[LinkDefaultAnnotation]) == 0 {
		return "", false
	}
	return f.Annotations[LinkDefaultAnnotation][0], true
}

func lookupFlag(cmd *cobra.Command, name string) *pflag.Flag {
	if f := cmd.Flags().Lookup(name); f != nil {
		return f
	}
	return cmd.InheritedFlags().Lookup(name)
}

// applyLinkDefaults is BuildRequest's last pass. Each string field that a
// linked project has a value for, and that neither a flag, --body nor stdin
// set, takes the link's value.
func applyLinkDefaults(cmd *cobra.Command, v reflect.Value, meta []FlagMeta) error {
	for _, m := range meta {
		if m.Kind != FlagKindString || FlagChanged(cmd, m.FlagName) {
			continue
		}
		value, ok := linkDefault(cmd, m.FlagName)
		if !ok || !fieldIsEmpty(v, m.FieldPath) {
			continue
		}
		if err := setFieldByPath(v, m.FieldPath, reflect.ValueOf(value)); err != nil {
			return fmt.Errorf("apply the linked --%s: %w", m.FlagName, err)
		}
	}
	return nil
}

// fieldIsEmpty reports whether the field at path holds its zero value, or
// sits behind a nil pointer. Unlike navigateToField it allocates nothing, so
// checking a field never creates an empty body.
func fieldIsEmpty(v reflect.Value, path string) bool {
	current := v
	for _, part := range strings.Split(path, ".") {
		for current.Kind() == reflect.Ptr {
			if current.IsNil() {
				return true
			}
			current = current.Elem()
		}
		if current.Kind() != reflect.Struct {
			return false
		}
		current = current.FieldByName(part)
		if !current.IsValid() {
			return false
		}
	}
	if current.Kind() == reflect.Ptr {
		return current.IsNil()
	}
	return current.IsZero()
}
